      path: "/etc/myapp/config.yml"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        let req = &config.requirements["local-config"];
        assert!(matches!(
            &req.check,
            CustomRequirementCheck::FileExists { path } if path == "/etc/myapp/config.yml"
        ));
    }

    #[test]
    fn empty_requirements_defaults() {
        let yaml = r#"
app_name: "TestApp"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        assert!(config.requirements.is_empty());
    }

    #[test]
    fn settings_default_environment_defaults_none() {
        let config: BivvyConfig = serde_yaml::from_str("").unwrap();
        assert!(config.settings.default_environment.is_none());
        assert!(config.settings.environments.is_empty());
    }

    #[test]
    fn parses_default_environment() {
        let yaml = r#"
settings:
  default_environment: staging
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        assert_eq!(
            config.settings.default_environment,
            Some("staging".to_string())
        );
    }

    #[test]
    fn parses_environment_config() {
        let yaml = r#"
settings:
  environments:
    ci:
      detect:
        - env: CI
        - env: GITHUB_ACTIONS
      default_workflow: ci
      provided_requirements:
        - docker
        - node
    staging:
      detect:
        - env: DEPLOY_ENV
          value: staging
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        assert_eq!(config.settings.environments.len(), 2);

        let ci = &config.settings.environments["ci"];
        assert_eq!(ci.detect.len(), 2);
        assert_eq!(ci.detect[0].env, "CI");
        assert!(ci.detect[0].value.is_none());
        assert_eq!(ci.default_workflow, Some("ci".to_string()));
        assert_eq!(ci.provided_requirements, vec!["docker", "node"]);

        let staging = &config.settings.environments["staging"];
        assert_eq!(staging.detect.len(), 1);
        assert_eq!(staging.detect[0].env, "DEPLOY_ENV");
        assert_eq!(staging.detect[0].value, Some("staging".to_string()));
        assert!(staging.default_workflow.is_none());
        assert!(staging.provided_requirements.is_empty());
    }

    #[test]
    fn parses_step_environments_override() {
        let yaml = r#"
steps:
  database:
    command: "rails db:setup"
    environments:
      ci:
        command: "rails db:schema:load"
        env:
          RAILS_ENV: test
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        let step = &config.steps["database"];
        assert_eq!(step.environments.len(), 1);

        let ci_override = &step.environments["ci"];
        assert_eq!(
            ci_override.command,
            Some("rails db:schema:load".to_string())
        );
        assert_eq!(
            ci_override.env.get("RAILS_ENV"),
            Some(&Some("test".to_string()))
        );
    }

    #[test]
    fn parses_step_only_environments() {
        let yaml = r#"
steps:
  seeds:
    command: "rails db:seed"
    only_environments:
      - development
      - staging
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        let step = &config.steps["seeds"];
        assert_eq!(step.only_environments, vec!["development", "staging"]);
    }

    #[test]
    fn step_only_environments_defaults_empty() {
        let yaml = r#"
            command: "echo hello"
        "#;
        let config: StepConfig = serde_yaml::from_str(yaml).unwrap();
        // Empty means "run in all environments"
        assert!(config.only_environments.is_empty());
    }

    #[test]
    fn step_environments_defaults_empty() {
        let yaml = r#"
            command: "echo hello"
        "#;
        let config: StepConfig = serde_yaml::from_str(yaml).unwrap();
        assert!(config.environments.is_empty());
    }

    #[test]
    fn environment_config_defaults() {
        let config: EnvironmentConfig = serde_yaml::from_str("").unwrap();
        assert!(config.detect.is_empty());
        assert!(config.default_workflow.is_none());
        assert!(config.provided_requirements.is_empty());
    }

    #[test]
    fn parses_nested_composite_checks() {
        let yaml = r#"
steps:
  complex:
    command: "echo complex"
    completed_check:
      type: all
      checks:
        - type: file_exists
          path: "required.txt"
        - type: any
          checks:
            - type: file_exists
              path: "option_a.txt"
            - type: file_exists
              path: "option_b.txt"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        let check = config.steps["complex"].completed_check.as_ref().unwrap();
        if let CompletedCheck::All { checks } = check {
            assert_eq!(checks.len(), 2);
            assert!(matches!(&checks[1], CompletedCheck::Any { .. }));
        } else {
            panic!("Expected All check");
        }
    }

    // --- 7A: Schema override parsing tests ---

    #[test]
    fn environment_override_depends_on_parses() {
        let yaml = r#"
            depends_on: [a, b]
        "#;
        let o: StepEnvironmentOverride = serde_yaml::from_str(yaml).unwrap();
        assert_eq!(o.depends_on, Some(vec!["a".to_string(), "b".to_string()]));
    }

    #[test]
    fn environment_override_watches_parses() {
        let yaml = r#"
            watches: []
        "#;
        let o: StepEnvironmentOverride = serde_yaml::from_str(yaml).unwrap();
        assert_eq!(o.watches, Some(vec![]));
    }

    #[test]
    fn environment_override_title_parses() {
        let yaml = r#"
            title: "CI Title"
        "#;
        let o: StepEnvironmentOverride = serde_yaml::from_str(yaml).unwrap();
        assert_eq!(o.title, Some("CI Title".to_string()));
    }

    // --- Vars parsing tests ---

    #[test]
    fn parses_static_var() {
        let yaml = r#"
vars:
  name: "bivvy"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        assert!(matches!(
            config.vars.get("name"),
            Some(VarDefinition::Static(v)) if v == "bivvy"
        ));
    }

    #[test]
    fn parses_computed_var() {
        let yaml = r#"
vars:
  v:
    command: "echo 1"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        assert!(matches!(
            config.vars.get("v"),
            Some(VarDefinition::Computed { command }) if command == "echo 1"
        ));
    }

    #[test]
    fn parses_mixed_vars() {
        let yaml = r#"
vars:
  app_name: "bivvy"
  version:
    command: "echo 1.0.0"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        assert_eq!(config.vars.len(), 2);
        assert!(matches!(
            config.vars.get("app_name"),
            Some(VarDefinition::Static(_))
        ));
        assert!(matches!(
            config.vars.get("version"),
            Some(VarDefinition::Computed { .. })
        ));
    }

    #[test]
    fn empty_vars_defaults() {
        let config: BivvyConfig = serde_yaml::from_str("").unwrap();
        assert!(config.vars.is_empty());
    }

    #[test]
    fn serialize_omits_empty_vars() {
        let config: BivvyConfig = serde_yaml::from_str("app_name: test").unwrap();
        let yaml = serde_yaml::to_string(&config).unwrap();
        assert!(!yaml.contains("vars"), "empty vars should be omitted");
    }

    // --- Precondition parsing tests ---

    #[test]
    fn parses_precondition_command_succeeds() {
        let yaml = r#"
steps:
  release:
    command: "git tag v1"
    precondition:
      type: command_succeeds
      command: "test $(git branch --show-current) = main"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        let step = &config.steps["release"];
        assert!(matches!(
            step.precondition,
            Some(CompletedCheck::CommandSucceeds { .. })
        ));
    }

    #[test]
    fn parses_precondition_all() {
        let yaml = r#"
steps:
  release:
    command: "git tag v1"
    precondition:
      type: all
      checks:
        - type: command_succeeds
          command: "test $(git branch --show-current) = main"
        - type: command_succeeds
          command: "git diff --quiet"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        let step = &config.steps["release"];
        if let Some(CompletedCheck::All { checks }) = &step.precondition {
            assert_eq!(checks.len(), 2);
        } else {
            panic!("Expected All precondition");
        }
    }

    #[test]
    fn precondition_defaults_none() {
        let yaml = r#"
            command: "echo hello"
        "#;
        let config: StepConfig = serde_yaml::from_str(yaml).unwrap();
        assert!(config.precondition.is_none());
    }

    #[test]
    fn serialize_omits_none_precondition() {
        let config: BivvyConfig = serde_yaml::from_str(
            r#"
steps:
  hello:
    command: "echo hello"
"#,
        )
        .unwrap();
        let yaml = serde_yaml::to_string(&config).unwrap();
        assert!(
            !yaml.contains("precondition"),
            "None precondition should be omitted"
        );
    }

    #[test]
    fn rejects_unknown_field_in_root_config() {
        let yaml = r#"
app_name: "MyApp"
stpes:
  test:
    command: "echo test"
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(result.is_err(), "Unknown field 'stpes' should be rejected");
        let msg = result.unwrap_err().to_string();
        assert!(
            msg.contains("unknown field"),
            "Error should mention 'unknown field', got: {}",
            msg
        );
    }

    #[test]
    fn rejects_unknown_field_in_settings() {
        let yaml = r#"
settings:
  default_outpt: verbose
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(
            result.is_err(),
            "Unknown field 'default_outpt' in settings should be rejected"
        );
    }

    #[test]
    fn rejects_unknown_field_in_step_config() {
        let yaml = r#"
steps:
  test:
    comand: "echo test"
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(
            result.is_err(),
            "Unknown field 'comand' in step should be rejected"
        );
    }

    #[test]
    fn rejects_unknown_field_in_workflow_config() {
        let yaml = r#"
workflows:
  default:
    stps: [test]
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(
            result.is_err(),
            "Unknown field 'stps' in workflow should be rejected"
        );
    }

    #[test]
    fn rejects_unknown_field_in_environment_config() {
        let yaml = r#"
settings:
  environments:
    ci:
      detct:
        - env: CI
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(
            result.is_err(),
            "Unknown field 'detct' in environment config should be rejected"
        );
    }

    #[test]
    fn environment_override_bare_null_parses_as_none() {
        let yaml = "command:";
        let o: StepEnvironmentOverride = serde_yaml::from_str(yaml).unwrap();
        assert!(o.command.is_none());
    }

    #[test]
    fn environment_override_empty_string_is_not_null() {
        let yaml = r#"command: """#;
        let o: StepEnvironmentOverride = serde_yaml::from_str(yaml).unwrap();
        assert_eq!(o.command, Some("".to_string()));
    }
}

